package com.inridemart.order;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.*;
@Entity @Table(name="orders", uniqueConstraints=@UniqueConstraint(columnNames={"user_id","idempotency_key"})) public class OrderEntity { @Id UUID id; @Column(name="user_id",nullable=false) UUID userId; @Column(name="idempotency_key",nullable=false) String idempotencyKey; @Enumerated(EnumType.STRING) @Column(nullable=false) OrderStatus status; @Column(nullable=false) BigDecimal totalAmount; @Column(nullable=false,length=3) String currency; @Column(nullable=false) Instant createdAt; @ElementCollection @CollectionTable(name="order_items",joinColumns=@JoinColumn(name="order_id")) List<OrderItemEntity> items=new ArrayList<>(); protected OrderEntity(){} OrderEntity(Order o){id=o.id();userId=o.userId();idempotencyKey=o.idempotencyKey();status=o.status();totalAmount=o.totalAmount();currency=o.currency();createdAt=o.createdAt();items=o.items().stream().map(OrderItemEntity::new).toList();} Order toDomain(){return new Order(id,userId,idempotencyKey,status,items.stream().map(OrderItemEntity::toDomain).toList(),totalAmount,currency,createdAt);} }
